{
  "analysis": "The v2 parser produced 365 moves, which is too many - it's double-counting commands due to scrollback overlap mismatches and OCR errors. The 1fps approach alone isn't sufficient. We need a more methodical approach: verify the final move count, use the moves counter to identify gaps, and selectively OCR higher-fps frames only in gap regions. Let me follow a cleaner strategy.",
  "plan": "First, verify the final moves count by extracting and OCR'ing the last frame. Then check the beginning of the moves progression file to identify all gap regions. This will tell us exactly where we need higher-fps frame extraction.",
  "commands": [
    {
      "keystrokes": "ffmpeg -y -sseof -1 -i /app/video.mp4 -frames:v 1 /tmp/last_frame.png 2>/dev/null\n",
      "duration": 1.0
    },
    {
      "keystrokes": "tesseract /tmp/last_frame.png stdout 2>/dev/null | head -20\n",
      "duration": 1.0
    },
    {
      "keystrokes": "wc -l /app/moves_progress.txt; head -60 /app/moves_progress.txt\n",
      "duration": 0.1
    },
    {
      "keystrokes": "grep -oE 'Moves: [0-9]+' /app/moves_progress.txt | grep -oE '[0-9]+' | sort -n | tail -1\n",
      "duration": 0.1
    }
  ],
  "task_complete": false
}
